/**
 * Keeping records safe on a device-only app: ask the browser not to evict our storage, and remind the user to
 * export a backup (the JSON export, which import.ts can restore) now and then.
 */

const LAST_EXPORT_KEY = 'fpc.lastExport.v1';
const SNOOZE_KEY = 'fpc.backupSnooze.v1';

/** Days without a backup after which the home screen reminds (once there are enough records to lose). */
export const BACKUP_REMIND = { days: 30, minSessions: 3, snoozeDays: 7 } as const;

const read = (k: string): string | null => {
  try {
    return localStorage.getItem(k);
  } catch {
    return null;
  }
};
const write = (k: string, v: string): void => {
  try {
    localStorage.setItem(k, v);
  } catch {
    /* private mode: reminder only for this visit */
  }
};

export const lastExport = (): string | null => read(LAST_EXPORT_KEY);

/** After deleting all data the old backup date would be misleading. */
export function forgetBackupMarks(): void {
  try {
    localStorage.removeItem(LAST_EXPORT_KEY);
    localStorage.removeItem(SNOOZE_KEY);
  } catch {
    /* private mode */
  }
}
export const markExported = (at: Date = new Date()): void => write(LAST_EXPORT_KEY, at.toISOString());
export const snoozeBackup = (at: Date = new Date()): void => write(SNOOZE_KEY, at.toISOString());

const daysSince = (iso: string | null, now: Date): number => (iso ? (now.getTime() - new Date(iso).getTime()) / 86_400_000 : Infinity);

/** Whether to remind: enough records, no backup for a while, not snoozed. */
export function backupDue(sessions: number, last: string | null, snoozed: string | null, now: Date = new Date()): boolean {
  if (sessions < BACKUP_REMIND.minSessions) return false;
  if (daysSince(snoozed, now) < BACKUP_REMIND.snoozeDays) return false;
  return daysSince(last, now) >= BACKUP_REMIND.days;
}

export const backupSnoozed = (): string | null => read(SNOOZE_KEY);

export interface StorageStatus {
  /** null when the browser cannot tell. */
  persisted: boolean | null;
  usageMb: number | null;
}

export async function storageStatus(): Promise<StorageStatus> {
  const s = typeof navigator !== 'undefined' ? navigator.storage : undefined;
  const persisted = s?.persisted ? await s.persisted().catch(() => null) : null;
  const est = s?.estimate ? await s.estimate().catch(() => null) : null;
  return { persisted, usageMb: est?.usage != null ? Math.round((est.usage / 1_048_576) * 10) / 10 : null };
}

/**
 * Asks the browser to keep this app's storage (no eviction when space runs low). Chrome decides silently (granted for
 * installed apps and often-used sites), Firefox may ask. Returns the result, or null when unsupported.
 */
export async function requestPersist(): Promise<boolean | null> {
  const s = typeof navigator !== 'undefined' ? navigator.storage : undefined;
  if (!s?.persist) return null;
  try {
    if (s.persisted && (await s.persisted())) return true;
    return await s.persist();
  } catch {
    return null;
  }
}
