/**
 * Per-frame capture-quality gate. Frames failing any criterion are excluded
 * from measurement; counts of each failure are reported to the user so the
 * capture can be corrected (risk control for mis-measurement, see RM-H01).
 */
import { eyeCenter, dist, rollFromEyes, toPixels } from './geometry';
import type { FrameObservation, FrameQuality, Pose, QualityIssue } from './types';

export interface QualityThresholds {
  maxYawDeg: number;
  maxPitchDeg: number;
  maxRollDeg: number;
  /** Minimum inter-eye distance as a fraction of the shorter image side. */
  minEyeDistanceFrac: number;
  minEyeDistancePx: number;
  /** Required landmark margin from the image border (normalised). */
  edgeMargin: number;
  minLuminance: number;
  maxLuminance: number;
  maxLuminanceAsymmetry: number;
}

export const DEFAULT_QUALITY: Readonly<QualityThresholds> = Object.freeze({
  // 8 → 5 (bench, tools/blender/BENCH.md): at an estimated yaw of ~5° the detected brow ratio was off by 0.18–0.37.
  maxYawDeg: 5,
  maxPitchDeg: 12,
  maxRollDeg: 10,
  minEyeDistanceFrac: 0.1,
  minEyeDistancePx: 48,
  edgeMargin: 0.01,
  minLuminance: 45,
  maxLuminance: 220,
  maxLuminanceAsymmetry: 0.25,
});

/** Landmark-only pose estimate used when no transformation matrix is given. */
function poseFromLandmarks(obs: FrameObservation, roll: number): Pose {
  const lm = obs.landmarks;
  // Face-contour points at ear level: 234 (patient right) and 454 (patient left).
  // MediaPipe z shares the x scale, so the depth difference between them gives yaw.
  const dx = (lm[454 * 3]! - lm[234 * 3]!) * obs.width;
  const dz = (lm[454 * 3 + 2]! - lm[234 * 3 + 2]!) * obs.width;
  const yaw = (Math.atan2(dz, dx) * 180) / Math.PI;
  return { yaw, pitch: 0, roll };
}

export function assessFrame(obs: FrameObservation, th: QualityThresholds = DEFAULT_QUALITY): FrameQuality {
  if (obs.landmarks.length < 468 * 3) {
    return { ok: false, issues: ['noFace'], pose: { yaw: 0, pitch: 0, roll: 0 }, eyeDistancePx: 0 };
  }
  const issues: QualityIssue[] = [];
  const px = toPixels(obs);
  // Roll is always measured from the eye line: it is exact for our purpose.
  const roll = rollFromEyes(px);
  const pose: Pose = obs.pose ? { yaw: obs.pose.yaw, pitch: obs.pose.pitch, roll } : poseFromLandmarks(obs, roll);

  if (Math.abs(pose.yaw) > th.maxYawDeg) issues.push('yaw');
  if (Math.abs(pose.pitch) > th.maxPitchDeg) issues.push('pitch');
  if (Math.abs(pose.roll) > th.maxRollDeg) issues.push('roll');

  const eyeDistancePx = dist(eyeCenter(px, 'right'), eyeCenter(px, 'left'));
  if (eyeDistancePx < th.minEyeDistancePx || eyeDistancePx < th.minEyeDistanceFrac * Math.min(obs.width, obs.height)) {
    issues.push('tooFar');
  }

  const lm = obs.landmarks;
  for (let i = 0; i < 468; i++) {
    const x = lm[3 * i]!;
    const y = lm[3 * i + 1]!;
    if (x < th.edgeMargin || x > 1 - th.edgeMargin || y < th.edgeMargin || y > 1 - th.edgeMargin) {
      issues.push('outOfFrame');
      break;
    }
  }

  if (obs.luminance) {
    if (obs.luminance.mean < th.minLuminance) issues.push('dark');
    else if (obs.luminance.mean > th.maxLuminance) issues.push('bright');
    if (obs.luminance.asymmetry > th.maxLuminanceAsymmetry) issues.push('unevenLight');
  }

  return { ok: issues.length === 0, issues, pose, eyeDistancePx };
}
