/**
 * MediaPipe Face Landmarker (478-point topology) index definitions.
 * "right"/"left" always means the patient's anatomical side. In an unmirrored
 * frontal image the patient's right side appears on the image's left.
 * Index semantics were cross-checked against FaceLandmarker.FACE_LANDMARKS_*.
 */
import type { Side } from './types';

export const NUM_LANDMARKS = 478;

export interface SideIndices {
  eyeOuter: number;
  eyeInner: number;
  /** Upper/lower eyelid point pairs used for palpebral fissure height. */
  lidPairs: ReadonlyArray<readonly [number, number]>;
  upperLid: readonly number[];
  lowerLid: readonly number[];
  /** Upper brow contour, lateral → mid-medial (frontalis-driven segment). */
  brow: readonly number[];
  mouthCorner: number;
  /** Nasal ala / alar base. */
  ala: readonly number[];
  /** Lateral upper-lip vermilion points (levator labii). */
  upperLip: readonly number[];
  cheek: readonly number[];
  /** Iris boundary points in cyclic order (opposite pairs: 0–2, 1–3). */
  iris: readonly [number, number, number, number];
}

