export const LIP_MID_LOWER = 17;

/**
 * Points assumed quasi-rigid during all test expressions (nasal dorsum, inner
 * canthi, temporal face contour). Used for similarity alignment of each
 * expression frame onto the rest reference.
 */
export const ALIGNMENT_ANCHORS: readonly number[] = [168, 6, 197, 195, 5, 4, 133, 362, 127, 356, 162, 389];

/**
 * Candidates for the robust alignment: the anchors above plus forehead and glabella points. Every expression
 * moves some of them (the nasal dorsum in a snarl, the cheek contour and nose tip in a broad smile, the forehead
 * in a brow raise) and tracking can lose one; the fit keeps the ALIGNMENT_KEEP that agree best.
 */
export const ALIGNMENT_CANDIDATES: readonly number[] = [...ALIGNMENT_ANCHORS, 10, 151, 9, 8, 108, 337, 67, 297, 109, 338];
export const ALIGNMENT_KEEP = 10;

