/** Lock screen: open with any registered method, a recovery code, or (all forgotten) wipe this device's records. */
import { useEffect, useState } from 'preact/hooks';
import {
  checkSecret,
  clearLock,
  loadLock,
  normalizeRecovery,
  patternKey,
  recordAttempt,
  registered,
  verifyBiometric,
  waitMs,
  type LockMethod,
} from '../../data/lock';
import { actions } from '../../data/store';
import { Icon } from '../icons';
import { Notice, Segmented } from './common';
import { PatternPad } from './PatternPad';

type Way = LockMethod | 'recovery' | 'reset';

const WAY_LABEL: Record<Way, string> = {
  biometric: '지문·얼굴',
  password: '비밀번호',
  pattern: '패턴',
  recovery: '복구 코드',
  reset: '모두 잊음',
};

export function LockScreen({ onUnlock }: { onUnlock: () => void }) {
  const cfg = loadLock();
  const methods = registered(cfg);
  const [way, setWay] = useState<Way>(methods[0] ?? 'recovery');
  const [text, setText] = useState('');
  const [msg, setMsg] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [wait, setWait] = useState(waitMs());
  const [bad, setBad] = useState(false);

  useEffect(() => {
    if (wait <= 0) return;
    const t = setTimeout(() => setWait(waitMs()), 1000);
    return () => clearTimeout(t);
  }, [wait]);

  const finish = (ok: boolean) => {
    recordAttempt(ok);
    if (ok) {
      onUnlock();
      return;
    }
    setBad(true);
    setMsg('맞지 않습니다. 다시 해 보거나 다른 방법으로 여세요.');
    setWait(waitMs());
    setTimeout(() => setBad(false), 900);
  };

  const tryBiometric = async () => {
    if (!cfg.biometric || busy) return;
    setBusy(true);
    setMsg(null);
    try {
      finish(await verifyBiometric(cfg.biometric));
    } catch {
      setMsg('지문·얼굴 인식이 취소되었거나 이 브라우저에서 쓸 수 없습니다. 다른 방법으로 여세요.');
    } finally {
      setBusy(false);
    }
  };

  const blocked = wait > 0;
  const ways: Way[] = [...methods, 'recovery', 'reset'];

  return (
    <div class="lock-screen">
      <div class="lock-card">
        <div style={{ color: 'var(--accent-ink)', width: '40px', height: '40px', margin: '0 auto' }}>
          <Icon name="shield" class="hero-icon" />
        </div>
        <h2 class="center" style={{ margin: '6px 0 2px' }}>
          앱이 잠겨 있습니다
        </h2>
        <p class="small ink2 center" style={{ margin: '0 0 10px' }}>
          등록한 방법 중 하나로 여세요.
        </p>
        <Segmented
          label="여는 방법"
          value={way}
          onChange={(v) => {
            setWay(v);
            setText('');
            setMsg(null);
          }}
          options={ways.map((w) => ({ value: w, label: WAY_LABEL[w] }))}
        />

        <div style={{ marginTop: '12px' }}>
          {blocked && (
            <Notice tone="warn">
              <span class="small">여러 번 틀려서 {Math.ceil(wait / 1000)}초 뒤에 다시 할 수 있습니다.</span>
            </Notice>
          )}
          {way === 'biometric' && (
            <button class="btn primary block" disabled={busy || blocked} onClick={tryBiometric}>
              <Icon name="shield" /> 지문·얼굴로 열기
            </button>
          )}
          {(way === 'password' || way === 'recovery') && (
            <form
              onSubmit={async (e) => {
                e.preventDefault();
                if (blocked || busy || !text) return;
                setBusy(true);
                const ok =
                  way === 'password' ? await checkSecret(text, cfg.password) : await checkSecret(normalizeRecovery(text), cfg.recovery);
                setBusy(false);
                setText('');
                finish(ok);
              }}
            >
              <input
                class="block"
                type={way === 'password' ? 'password' : 'text'}
                autoComplete="off"
                autoCapitalize={way === 'recovery' ? 'characters' : 'off'}
                placeholder={way === 'password' ? '비밀번호' : 'XXXX-XXXX-XXXX-XXXX'}
                aria-label={way === 'password' ? '비밀번호' : '복구 코드'}
                value={text}
                disabled={blocked}
                onInput={(e) => setText((e.target as HTMLInputElement).value)}
              />
              <button class="btn primary block" style={{ marginTop: '8px' }} disabled={busy || blocked || !text}>
                열기
              </button>
            </form>
          )}
          {way === 'pattern' && (
            <div class="center">
              <PatternPad
                disabled={blocked || busy}
                error={bad}
                onDone={async (dots) => {
                  setBusy(true);
                  const ok = await checkSecret(patternKey(dots), cfg.pattern);
                  setBusy(false);
                  finish(ok);
                }}
              />
            </div>
          )}
          {way === 'reset' && (
            <div>
              <Notice tone="danger">
                <span class="small">
                  등록한 방법과 복구 코드를 모두 잊었다면, 이 기기의 기록을 모두 지우고 새로 시작해야 합니다. 백업 파일(JSON)이 있으면 새로
                  시작한 뒤 설정 → ‘기록 가져오기’로 되살릴 수 있습니다.
                </span>
              </Notice>
              <input
                class="block"
                type="text"
                placeholder="지우려면 ‘삭제’라고 입력"
                aria-label="삭제 확인"
                value={text}
                onInput={(e) => setText((e.target as HTMLInputElement).value)}
              />
              <button
                class="btn block"
                style={{ marginTop: '8px', background: 'var(--critical)', color: '#fff' }}
                disabled={text.trim() !== '삭제'}
                onClick={async () => {
                  await actions.deleteAll();
                  clearLock();
                  location.hash = '/';
                  onUnlock();
                }}
              >
                이 기기의 기록 모두 지우고 새로 시작
              </button>
            </div>
          )}
          {msg && (
            <p class="small center" style={{ color: 'var(--critical)', margin: '8px 0 0' }}>
              {msg}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
