/**
 * Algorithm identity. Any change to landmark sets, formulas, thresholds or
 * aggregation MUST bump ALGORITHM_VERSION (and SCORING_VERSION for scoring
 * changes), because every stored assessment records these values and results
 * from different versions must never be silently compared.
 */
export const ALGORITHM_ID = 'FPA-GEOM';
export const ALGORITHM_VERSION = '0.5.0';
export const SCORING_VERSION = 'SC-0.2.0';
