/**
 * App lock (optional): a screen lock over the app, opened by any one of several registered methods — a password, a
 * pattern, the phone's fingerprint/face unlock (WebAuthn platform authenticator) — or a recovery code shown once when
 * the lock is turned on. Registering at least two methods is required so one forgotten method never locks the user out.
 *
 * Secrets are stored only as salted PBKDF2-SHA-256 hashes (this device, localStorage). The lock guards the screen; the
 * stored records themselves are protected by the phone's own lock and the browser (docs/09 TM-08).
 */

export type LockMethod = 'password' | 'pattern' | 'biometric';

interface Hashed {
  salt: string;
  hash: string;
  iter: number;
}

export interface LockConfig {
  enabled: boolean;
  /** Minutes in the background before locking again (0 = every time the app is left). */
  relockMin: number;
  password?: Hashed;
  pattern?: Hashed;
  biometric?: { credentialId: string; publicKey: string | null; alg: number };
  recovery?: Hashed;
}

const KEY = 'fpc.lock.v1';
const ATTEMPTS_KEY = 'fpc.lock.attempts.v1';
export const PBKDF2_ITER = 150_000;
export const MIN_METHODS = 2;
export const PATTERN_MIN_DOTS = 4;
export const PASSWORD_MIN = 4;

const b64 = (a: ArrayBuffer | Uint8Array): string => {
  const u = a instanceof Uint8Array ? a : new Uint8Array(a);
  let s = '';
  for (const x of u) s += String.fromCharCode(x);
  return btoa(s);
};
const unb64 = (s: string): Uint8Array => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const b64url = (a: ArrayBuffer | Uint8Array): string => b64(a).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

export function loadLock(): LockConfig {
  try {
    const v = localStorage.getItem(KEY);
    if (v) return JSON.parse(v) as LockConfig;
  } catch {
    /* private mode or damaged: no lock */
  }
  return { enabled: false, relockMin: 1 };
}

export function saveLock(c: LockConfig): void {
  try {
    localStorage.setItem(KEY, JSON.stringify(c));
  } catch {
    /* private mode: the lock cannot persist */
  }
}

/** Removes the lock entirely (all methods). */
export function clearLock(): void {
  try {
    localStorage.removeItem(KEY);
    localStorage.removeItem(ATTEMPTS_KEY);
  } catch {
    /* private mode */
  }
}

export const registered = (c: LockConfig): LockMethod[] => (['password', 'pattern', 'biometric'] as const).filter((m) => !!c[m]);

async function pbkdf2(secret: string, salt: Uint8Array, iter: number): Promise<string> {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: salt as BufferSource, iterations: iter }, key, 256);
  return b64(bits);
}

export async function hashSecret(secret: string, iter = PBKDF2_ITER): Promise<Hashed> {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return { salt: b64(salt), hash: await pbkdf2(secret, salt, iter), iter };
}

export async function checkSecret(secret: string, h: Hashed | undefined): Promise<boolean> {
  if (!h) return false;
  const got = await pbkdf2(secret, unb64(h.salt), h.iter);
  // Constant-time comparison of equal-length base64 strings.
  if (got.length !== h.hash.length) return false;
  let d = 0;
  for (let i = 0; i < got.length; i++) d |= got.charCodeAt(i) ^ h.hash.charCodeAt(i);
  return d === 0;
}

/** A pattern is the sequence of dots (0–8 on a 3×3 grid). */
export const patternKey = (dots: readonly number[]): string => `pattern:${dots.join('-')}`;

export const validPattern = (dots: readonly number[]): boolean =>
  dots.length >= PATTERN_MIN_DOTS && new Set(dots).size === dots.length && dots.every((d) => Number.isInteger(d) && d >= 0 && d <= 8);

/** Recovery code: 16 characters without look-alikes, shown as 4 groups (e.g. K7QM-2XRP-9HTD-C4WA). */
export function newRecoveryCode(): string {
  const A = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const r = crypto.getRandomValues(new Uint8Array(16));
  const s = Array.from(r, (x) => A[x % A.length]).join('');
  return s.match(/.{4}/g)!.join('-');
}

export const normalizeRecovery = (input: string): string =>
  input
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '')
    .replace(/(.{4})(?=.)/g, '$1-');

/** Wrong attempts slow down: 5 free tries, then 30 s, doubling up to 15 min. */
export function lockoutMs(failures: number): number {
  if (failures < 5) return 0;
  return Math.min(15 * 60_000, 30_000 * 2 ** (failures - 5));
}

interface Attempts {
  failures: number;
  last: number;
}

export function readAttempts(): Attempts {
  try {
    const v = localStorage.getItem(ATTEMPTS_KEY);
    if (v) return JSON.parse(v) as Attempts;
  } catch {
    /* ignore */
  }
  return { failures: 0, last: 0 };
}

export function recordAttempt(ok: boolean, now = Date.now()): Attempts {
  const a = ok ? { failures: 0, last: now } : { failures: readAttempts().failures + 1, last: now };
  try {
    localStorage.setItem(ATTEMPTS_KEY, JSON.stringify(a));
  } catch {
    /* ignore */
  }
  return a;
}

/** Milliseconds until the next try is allowed (0 = now). */
export function waitMs(now = Date.now()): number {
  const a = readAttempts();
  return Math.max(0, a.last + lockoutMs(a.failures) - now);
}

// ---------- Fingerprint / face unlock (WebAuthn platform authenticator) ----------

export async function biometricAvailable(): Promise<boolean> {
  const P = typeof window !== 'undefined' ? window.PublicKeyCredential : undefined;
  if (!P?.isUserVerifyingPlatformAuthenticatorAvailable) return false;
  try {
    return await P.isUserVerifyingPlatformAuthenticatorAvailable();
  } catch {
    return false;
  }
}

/** Registers the phone's fingerprint/face unlock for this app (a passkey kept on the device). */
export async function registerBiometric(): Promise<NonNullable<LockConfig['biometric']>> {
  const cred = (await navigator.credentials.create({
    publicKey: {
      challenge: crypto.getRandomValues(new Uint8Array(32)),
      rp: { name: '안면마비 케어 앱 잠금' },
      user: { id: crypto.getRandomValues(new Uint8Array(16)), name: 'app-lock', displayName: '앱 잠금' },
      pubKeyCredParams: [
        { type: 'public-key', alg: -7 },
        { type: 'public-key', alg: -257 },
      ],
      authenticatorSelection: { authenticatorAttachment: 'platform', userVerification: 'required', residentKey: 'discouraged' },
      timeout: 60_000,
      attestation: 'none',
    },
  })) as PublicKeyCredential | null;
  if (!cred) throw new Error('cancelled');
  const res = cred.response as AuthenticatorAttestationResponse;
  const spki = typeof res.getPublicKey === 'function' ? res.getPublicKey() : null;
  const alg = typeof res.getPublicKeyAlgorithm === 'function' ? res.getPublicKeyAlgorithm() : -7;
  return { credentialId: b64url(cred.rawId), publicKey: spki ? b64(spki) : null, alg };
}

/** DER ECDSA signature → raw r‖s (64 bytes), as WebCrypto expects. */
function derToRaw(der: Uint8Array): Uint8Array {
  let i = 2;
  const read = () => {
    i++; // INTEGER tag 0x02
    const len = der[i++]!;
    let v = der.slice(i, i + len);
    i += len;
    while (v.length > 32 && v[0] === 0) v = v.slice(1);
    const out = new Uint8Array(32);
    out.set(v, 32 - v.length);
    return out;
  };
  const r = read();
  const s = read();
  const raw = new Uint8Array(64);
  raw.set(r, 0);
  raw.set(s, 32);
  return raw;
}

/** Asks for the fingerprint/face unlock and checks the signed answer (challenge, user verification, signature). */
export async function verifyBiometric(b: NonNullable<LockConfig['biometric']>): Promise<boolean> {
  const challenge = crypto.getRandomValues(new Uint8Array(32));
  const idBytes = unb64(b.credentialId.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((b.credentialId.length + 3) % 4));
  const cred = (await navigator.credentials.get({
    publicKey: {
      challenge,
      allowCredentials: [{ type: 'public-key', id: idBytes as BufferSource }],
      userVerification: 'required',
      timeout: 60_000,
    },
  })) as PublicKeyCredential | null;
  if (!cred) return false;
  const res = cred.response as AuthenticatorAssertionResponse;
  const client = JSON.parse(new TextDecoder().decode(res.clientDataJSON)) as { type: string; challenge: string };
  if (client.type !== 'webauthn.get' || client.challenge !== b64url(challenge)) return false;
  const auth = new Uint8Array(res.authenticatorData);
  const userVerified = (auth[32]! & 0x04) !== 0;
  if (!userVerified) return false;
  if (!b.publicKey) return true; // Older browsers do not expose the key: the platform's own verification is trusted.
  const hash = new Uint8Array(await crypto.subtle.digest('SHA-256', res.clientDataJSON));
  const signed = new Uint8Array(auth.length + hash.length);
  signed.set(auth, 0);
  signed.set(hash, auth.length);
  const spki = unb64(b.publicKey);
  if (b.alg === -257) {
    const key = await crypto.subtle.importKey('spki', spki as BufferSource, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, [
      'verify',
    ]);
    return crypto.subtle.verify('RSASSA-PKCS1-v1_5', key, res.signature, signed as BufferSource);
  }
  const key = await crypto.subtle.importKey('spki', spki as BufferSource, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']);
  return crypto.subtle.verify(
    { name: 'ECDSA', hash: 'SHA-256' },
    key,
    derToRaw(new Uint8Array(res.signature)) as BufferSource,
    signed as BufferSource,
  );
}
